function node(tag,attrs={},...children){const e=document.createElement(tag);for(const[k,v]of Object.entries(attrs)){if(v===undefined||v===null)continue;if(k==='class')e.className=v;else if(k==='text')e.textContent=v;else if(k.startsWith('on'))e.addEventListener(k.slice(2),v);else if(k==='checked'||k==='disabled'||k==='hidden')e[k]=Boolean(v);else e.setAttribute(k,String(v));}for(const c of children.flat()){if(c!==undefined&&c!==null)e.append(c instanceof Node?c:document.createTextNode(String(c)));}return e;}
