  form.addEventListener('submit',event=>{event.preventDefault();runSearch({question:input.value,options:localOptions,page:input.value===initial?Math.max(1,Number(params.get('page'))||1):1,hash:input.value===initial?(params.get('questionhashed')||params.get('question_hashed')):undefined});});
